import{_ as o,a as c}from"./chunks/palace@2x.07328b4c.js";import{D as t}from"./chunks/donate.3a95be8c.js";import{o as a,c as d,O as r,X as e}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const p=e('<h1 id="紫微斗数星盘" tabindex="-1">紫微斗数の命盤 <a class="header-anchor" href="#紫微斗数星盘" aria-label="Permalink to &quot;紫微斗数の命盤  {#紫微斗数星盘}&quot;">​</a></h1><h2 id="前言" tabindex="-1">はじめに <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;はじめに  {#前言}&quot;">​</a></h2><p>紫微斗数の<code>星盤</code>は<code>命盤</code>とも呼ばれ、出生した日付と時辰から計算した、<a href="./palace"><code>宮位</code></a>と<a href="./star"><code>星曜</code></a>の配置を示す図です。命盤には<code>本命盤</code>・<code>大限盤</code>・<code>流年盤</code>があり、運勢を見る際はこの3つを重ねて分析します。紫微斗数を初めて学ぶ方は、先に<a href="./basis">基礎知識</a>を読んでからこのページに進むと、ここで使う用語を理解しやすくなります。</p><blockquote><p><em>このシリーズの記事はオリジナルです。転載の際は出典を明記してください。</em></p></blockquote>',4),l=e('<h2 id="如何排盘" tabindex="-1">命盤の作成方法 <a class="header-anchor" href="#如何排盘" aria-label="Permalink to &quot;命盤の作成方法 {#如何排盘}&quot;">​</a></h2><p>命盤の作成に必要なのは、出生の<code>日付</code>、<a href="./basis#十二时辰"><code>時間</code></a>、<code>性別</code>だけです。この情報を使い、<a href="./setup"><code>安星訣</code></a>に沿って49の手順を進めると、命盤全体を作成できます。ただし、<code>命盤の解釈</code>だけをしたい場合は、命盤の作成方法を理解したり安星訣を暗記したりする必要はありません。</p><p>完成した命盤は、おおよそ次のようになります。</p><p><img src="'+o+'" alt="紫微斗数の命盤"></p><p>命盤の文字を一つずつ読めても、全体として何を意味するのかはまだ分からないかもしれません。焦らなくて大丈夫です。本サイトの内容を学んでいけば、全体像が見えてきます。では、この命盤に書かれていることを説明しましょう。</p><h2 id="认识星盘" tabindex="-1">命盤の見方 <a class="header-anchor" href="#认识星盘" aria-label="Permalink to &quot;命盤の見方 {#认识星盘}&quot;">​</a></h2><p>外周の12個の小さな枠は<a href="./palace">十二人事宮</a>、略して<code>十二宮</code>です。中央の大きな枠は<code>中宮</code>と呼び、通常は基本情報を表示しますが、好きな情報を入れられます。中央の赤い矢印のような図は<code>三方四正</code>の関係を示しています。矢の先端が指す宮は<code>命宮</code>、矢の尾がある宮は命宮の<code>対宮の位置</code>、左右の翼の先端が指す宮は命宮の<code>三方の位置</code>です。詳しくは<a href="./palace">宮位のしくみ</a>で説明します。</p><p>外周の十二宮は、書かれている内容は異なりますが、配置は共通しています。ここでは1つの宮を取り上げて説明します。</p><p><img src="'+c+'" alt="紫微斗数の宮位"></p><p>上の図に含まれる情報は次のとおりです。</p><ul><li><p><code>主星</code></p><p>画像左上の<code>廉貞</code>と<code>貪狼</code>が<a href="./major-star">主星</a>で、次の<code>陷</code>が主星の明るさです。</p></li><li><p><code>補助星</code></p><p>図の上部中央にある<code>地空</code>・<code>地劫</code>・<code>陀羅</code>は<a href="./minor-star">補助星</a>です。主星と同じく、<code>陷</code>はその星曜の輝度を示します。すべての星曜に<code>明るさ</code>が表示されるわけではありません。詳しくは<a href="./star">紫微斗数の星曜</a>で説明します。</p></li><li><p><code>雑曜</code></p><p>画像右上の<code>天才</code>、<code>天壽</code>、<code>天廚</code>、<code>天月</code>は<a href="./adj-star">雑曜</a>です。</p></li><li><p><code>流曜</code></p><p>図の左側中央にある<code>年の曲</code>と<code>年の陀</code>は<a href="./star#流曜">流曜</a>です。</p></li><li><p><code>神煞</code></p><p>画像の左下に小さい文字で示した <code>長生</code> <code>官府</code> と右下に小さい文字で示した <code>白虎</code> <code>指背</code> を <a href="./star#四十八神煞">神煞</a> と呼び、次のように分けられます。</p><ul><li><code>長生</code>：長生十二神の1つ</li><li><code>官府</code>：博士十二神の1つ</li><li><code>指背</code>：流年の将前十二神の1つ</li><li><code>白虎</code>：流年の歳前十二神の1つ</li></ul></li><li><p><code>小限</code></p><p>図の下部にある数字<code>3 15 27 39 51 63 75 87 99 111</code>は<code>小限</code>を示します。数字は<code>数え年</code>で、3歳、15歳、27歳……のときに<code>小限</code>がこの宮に巡ることを意味します。</p></li><li><p><code>大限</code></p><p>図の下部の太字<code>33 - 42</code>は<code>大限</code>を示します。数え年の<code>33歳</code>から<code>42歳</code>までの10年間、<code>大限</code>がこの宮に巡ることを意味します。</p></li><li><p><code>宮名</code></p><p>図の左下にある<code>田宅</code>は、この宮の<code>宮名</code>です。</p></li><li><p><code>干支</code></p><p>図の右下にある<code>癸亥</code>はこの宮の<code>干支</code>で、そのうち<code>癸</code>を<code>宮干</code>と呼びます。この宮は、話の中では<code>亥の宮</code>と呼ぶこともできます。</p></li><li><p><code>四化</code></p><p>貪狼の後ろにある<code>忌</code>は<a href="./mutagen">四化星</a>を示し、ここでは生年の化忌です。背景が赤なら化祿、青なら化權、緑なら化科、黒なら化忌を表します。貪狼の前にある小さな黒い印は<code>自化</code>を示し、四化と同じ色分けを使います。この例では、貪狼が自化忌していることを表します。</p></li></ul><h2 id="如何解盘" tabindex="-1">命盤の読み解き方 <a class="header-anchor" href="#如何解盘" aria-label="Permalink to &quot;命盤の読み解き方 {#如何解盘}&quot;">​</a></h2><p>命盤には多くの情報があり、初心者はどこから見ればよいか分からず戸惑いがちです。これは紫微斗数を学ぶ際の大きな壁の1つです。ここでは命盤の読み方と手順を紹介します。順序に沿って少しずつ命盤に慣れ、やがて一目で大まかな特徴をつかめるようにしていきましょう。</p><div class="tip custom-block"><p class="custom-block-title">ヒント</p><p>各流派には独自の命盤の読み方や技法があります。本サイトでは流派ごとに内容を分けず、紫微斗数について研究し、整理したことを紹介しています。より分かりやすく学び、その楽しさを感じていただくことが目的です。</p></div><ol><li><p>命宮を見つける</p><p>命盤を読む最初の一歩は、<code>命宮</code>の位置を見つけることです。食べる前に口がどこにあるか分かっている必要があるのと同じくらい、基本となる出発点です。</p></li><li><p>主星を見る</p><p>命宮にある<code>主星</code>が、その人の<code>主星</code>です。「私は<code>紫微</code>」「彼女は<code>貪狼</code>」と言うときは、命宮の主星を指しています。<code>空宮</code>には主星がないため、<code>対宮</code>の主星を借りて読みます。用語が分からない場合は<a href="./basis#术语解释">用語解説</a>を参照してください。主星が分かれば、その性質をもとに命盤の持ち主の個性を分析できます。各主星の特徴は<a href="./major-star">十四主星</a>で詳しく説明します。</p></li><li><p>三方四正を見る</p><p><code>命宮</code>の<code>三方四正</code>に関わる他の宮は、<code>遷移</code>宮・<code>官祿</code>宮・<code>財帛</code>宮です。これらが人生にとって重要な領域であることは、想像しやすいでしょう。そのため、伝統的な紫微斗数の解釈では三方四正の吉凶を重視します。ただし、命盤には<code>バランス</code>も必要です。1つの宮が突出して優れていることよりも、<code>弱点</code>が可能性の上限を左右するからです。各宮の意味と役割は<a href="./palace">宮位のしくみ</a>で詳しく説明します。</p></li><li><p>福德宮を見る</p><p>福德宮は、その人の<code>精神面</code>を表し、好みや思考の傾向を示します。<code>三方四正</code>と<code>福德</code>宮を合わせて見ると、大まかな性格や行動の傾向を描けます。</p></li><li><p>生年四化の影響を見る</p><p>四化星は、命盤の持ち主の<code>内面</code>に影響します。<code>祿</code>のある宮は<code>喜び</code>を感じる領域で、<code>權</code>のある宮は<code>支配</code>したいと感じる領域です。<code>科</code>のある宮では<code>面目が立つ感覚</code>が得られ、その領域を人に<code>見せること</code>を好みます。一方、<code>忌</code>のある宮は<code>葛藤</code>や面目を失う感覚につながり、その領域を人に<code>見せること</code>や、そのことについて<code>話す</code>ことをためらいがちです。<code>劣等感</code>や<code>自信のなさ</code>の原因にもなります。これは本人の主観的な感覚であり、他人も同じように感じるとは限りません。詳しくは<a href="./mutagen">四化星</a>で説明します。</p></li><li><p>宮干四化を見る</p><p><code>運限</code>と<code>本命</code>の天干だけでなく、各宮の<code>宮干</code>も<code>四化</code>を起こします。宮干四化は宮同士の相互作用や関係性を示します。その分析によって、<code>パートナーとの関係はどうですか？</code>、<code>私の仕事はどうですか？</code>といったことを読み取れます。</p></li><li><p>関心のある宮位を分析する</p><p>対象となる宮位は、命盤の持ち主が特に関心を持っている領域の宮です。その宮にある<code>星曜</code>と、宮干から生じる<code>四化</code>を見て、その領域が本人に与える影響を分析します。</p></li><li><p>運限を見る</p><p>ここまでの手順は、命盤の持ち主の<code>静的情報</code>を分析するものです。絵の下書きで何をどこにどの大きさで描くかを決めるように、全体の輪郭を作ります。運限の分析は、その輪郭に細部を描き加える作業です。運限を層ごとに見ることで、環境が時期に応じて本人に与える影響を読み取れます。運限によって影響の範囲や結果は異なります。詳しくは<a href="./horoscope">紫微斗数の運限</a>を参照してください。</p></li></ol>',15),g=JSON.parse('{"title":"紫微斗数の命盤：構造と読み方","description":"紫微斗数の命盤に記載される情報と、命盤の基本的な見方を解説します。","frontmatter":{"title":"紫微斗数の命盤：構造と読み方","description":"紫微斗数の命盤に記載される情報と、命盤の基本的な見方を解説します。","head":[["link",{"rel":"canonical","href":"https://iztro.com/ja_JP/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/astrolabe"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/astrolabe"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"紫微斗数の命盤：構造と読み方 | 紫微研习社"}],["meta",{"property":"og:description","content":"紫微斗数の命盤に記載される情報と、命盤の基本的な見方を解説します。"}],["meta",{"property":"og:url","content":"https://iztro.com/ja_JP/learn/astrolabe"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"紫微斗数の命盤：構造と読み方 | 紫微研习社"}],["meta",{"name":"twitter:description","content":"紫微斗数の命盤に記載される情報と、命盤の基本的な見方を解説します。"}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/astrolabe#webpage\\",\\"url\\":\\"https://iztro.com/ja_JP/learn/astrolabe\\",\\"name\\":\\"紫微斗数の命盤：構造と読み方 | 紫微研习社\\",\\"description\\":\\"紫微斗数の命盤に記載される情報と、命盤の基本的な見方を解説します。\\",\\"inLanguage\\":\\"ja-JP\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/ja_JP/learn/astrolabe#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/ja_JP/learn/astrolabe#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/ja_JP/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"紫微斗数の命盤：構造と読み方\\",\\"item\\":\\"https://iztro.com/ja_JP/learn/astrolabe\\"}]}]}"]]},"headers":[],"relativePath":"ja_JP/learn/astrolabe.md","filePath":"ja_JP/learn/astrolabe.md"}'),i={name:"ja_JP/learn/astrolabe.md"},u=Object.assign(i,{setup(n){return(s,m)=>(a(),d("div",null,[p,r(t),l]))}});export{g as __pageData,u as default};
